const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Buffer } = require('buffer');

// Custom binary protocol parser for legacy system integration
class BinaryMessageParser {
  constructor(maxSize = 1024) {
    this.maxSize = maxSize;
    this.buffer = Buffer.alloc(maxSize);
    this.offset = 0;
  }

  // Parse variable-length encoded message from client
  parseMessage(inputHex) {
    const input = Buffer.from(inputHex, 'hex');
    // First 4 bytes: declared payload length (little-endian)
    const declaredLength = input.readUInt32LE(0);
    // Next 4 bytes: message type
    const msgType = input.readUInt32LE(4);
    // Remaining: payload data
    const payload = input.slice(8);

    // BUG: Uses declaredLength from untrusted input without bounds check
    // against actual buffer size or payload.length
    // This allows heap buffer overflow when declaredLength > this.maxSize
    for (let i = 0; i < declaredLength; i++) {
      this.buffer[this.offset + i] = payload[i] || 0x00;
    }
    this.offset += declaredLength;

    return {
      type: msgType,
      data: this.buffer.slice(0, this.offset).toString('utf8'),
      bytesWritten: declaredLength
    };
  }

  reset() {
    this.buffer.fill(0);
    this.offset = 0;
  }
}

const parser = new BinaryMessageParser(256);

const typeDefs = gql`
  type Query {
    health: String
    deviceStatus(deviceId: String!): DeviceStatus
  }

  type Mutation {
    sendDeviceCommand(deviceId: String!, commandPayload: String!): CommandResult
  }

  type DeviceStatus {
    online: Boolean
    lastSeen: String
    firmware: String
  }

  type CommandResult {
    success: Boolean
    response: String
    bytesProcessed: Int
  }
`;

const resolvers = {
  Query: {
    health: () => 'OK',
    deviceStatus: (_, { deviceId }) => ({
      online: true,
      lastSeen: new Date().toISOString(),
      firmware: '2.4.1'
    })
  },
  Mutation: {
    sendDeviceCommand: (_, { deviceId, commandPayload }) => {
      try {
        // commandPayload is hex-encoded binary from IoT device proxy
        parser.reset();
        const result = parser.parseMessage(commandPayload);
        return {
          success: true,
          response: result.data,
          bytesProcessed: result.bytesWritten
        };
      } catch (err) {
        return {
          success: false,
          response: err.message,
          bytesProcessed: 0
        };
      }
    }
  }
};

const app = express();

// Request size limit - but this doesn't prevent the overflow
// since small hex strings can declare large lengths
app.use(express.json({ limit: '1mb' }));

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false
});

server.applyMiddleware({ app, path: '/graphql' });

const PORT = process.env.PORT || 4000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`IoT Command Gateway running on port ${PORT}`);
});
